var WC_STOP={'the':1,'a':1,'an':1,'and':1,'or':1,'of':1,'to':1,'in':1,'is':1,'are':1,'was':1,'be':1,'on':1,'for':1,'with':1,'that':1,'this':1,'it':1,'as':1,'at':1,'by':1,'from':1,'not':1,'but':1,'means':1,'need':1};
function wcTokenize(text){
  if(typeof text!=='string'||!text.trim()) return { value:null, error:'文本为空' };
  var out=[], re=/[a-zA-Z][a-zA-Z0-9'-]*|[\u4e00-\u9fa5]+|\d+/g, m;
  while((m=re.exec(text))!==null){
    var t=m[0];
    if(/^[\u4e00-\u9fa5]+$/.test(t)){
      if(t.length<=2){ out.push(t); }
      else { for(var i=0;i+2<=t.length;i++) out.push(t.slice(i,i+2)); }
    } else out.push(t.toLowerCase());
  }
  return { value:out, error:null };
}
function wcCount(tokens, opts){
  var o=opts||{}, stop=o.stopwords!==false, min=o.minLen||2;
  var map={};
  for(var i=0;i<tokens.length;i++){
    var t=tokens[i];
    if(t.length<min) continue;
    if(stop && WC_STOP[t]) continue;
    map[t]=(map[t]||0)+1;
  }
  var arr=Object.keys(map).map(function(k){ return { word:k, count:map[k] }; });
  arr.sort(function(a,b){ return b.count-a.count || (a.word<b.word?-1:1); });
  return arr;
}
function wcLayout(freqs, opts){
  var o=opts||{}, W=o.width||640, H=o.height||360, maxN=o.max||40;
  var items=freqs.slice(0,maxN);
  if(!items.length) return { value:null, error:'无有效词' };
  var top=items[0].count, low=items[items.length-1].count;
  var placed=[];
  function box(x,y,w,h){ return { x:x-w/2, y:y-h/2, w:w, h:h }; }
  function hits(b){
    if(b.x<0||b.y<0||b.x+b.w>W||b.y+b.h>H) return true;
    for(var i=0;i<placed.length;i++){
      var p=placed[i].bb;
      if(b.x<p.x+p.w && b.x+b.w>p.x && b.y<p.y+p.h && b.y+b.h>p.y) return true;
    }
    return false;
  }
  for(var i=0;i<items.length;i++){
    var f=items[i];
    var size=top===low?24:Math.round(14+(f.count-low)/(top-low)*30);
    var w=f.word.length*size*0.62+6, h=size*1.15;
    var ang=0, r=0, done=false;
    while(r<Math.max(W,H)){
      var x=W/2+r*Math.cos(ang), y=H/2+r*Math.sin(ang)*0.62;
      var b=box(x,y,w,h);
      if(!hits(b)){ placed.push({ word:f.word, count:f.count, size:size, x:x, y:y, bb:b }); done=true; break; }
      ang+=0.35; r+=0.55;
    }
    if(!done) break;
  }
  return { value:{ items:placed, width:W, height:H }, error:null };
}
function wcEsc(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function wcSvg(text, opts){
  var t=wcTokenize(text);
