  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+L.value.width+'" height="'+L.value.height+'" viewBox="0 0 '+L.value.width+' '+L.value.height+'">';
  s+='<rect width="'+L.value.width+'" height="'+L.value.height+'" fill="#0A0A0B"/>';
  for(var i=0;i<L.value.items.length;i++){
    var it=L.value.items[i];
    s+='<text x="'+Math.round(it.x)+'" y="'+Math.round(it.y)+'" text-anchor="middle" dominant-baseline="middle" font-size="'+it.size+'" fill="'+PAL[i%PAL.length]+'" font-family="system-ui,sans-serif" font-weight="'+(i<3?700:400)+'">'+wcEsc(it.word)+'</text>';
  }
  s+='</svg>';
  return { value:s, error:null };
